package com.bosskillmilestones;

import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.*;

public class GrindProgressTest
{
	@Test public void milestonesAdvanceAtEveryBoundary()
	{
		assertEquals(10, GrindProgress.nextMilestone(0));
		assertEquals(10, GrindProgress.nextMilestone(9));
		assertEquals(25, GrindProgress.nextMilestone(10));
		assertEquals(50, GrindProgress.nextMilestone(25));
		assertEquals(100, GrindProgress.nextMilestone(50));
		assertEquals(150, GrindProgress.nextMilestone(149));
		assertEquals(200, GrindProgress.nextMilestone(150));
		assertTrue(GrindProgress.nextMilestone(Integer.MAX_VALUE) > Integer.MAX_VALUE);
	}

	@Test public void lifetimeGoalHandlesUnknownAndEstimates()
	{
		assertNull(GrindProgress.total("Unknown"));
		assertEquals(Integer.valueOf(1250), GrindProgress.total("~1,250"));
	}

	@Test public void choosesNearestFriendAndCountsOvertakeNotTie()
	{
		FriendLeaderboard.View view = new FriendLeaderboard.View(Arrays.asList(
			new FriendLeaderboard.Row("Far", 200, ""), new FriendLeaderboard.Row("Near", 123, ""),
			new FriendLeaderboard.Row("Ryan", 100, "")), "Updated");
		assertEquals("Near: 24 to pass", GrindProgress.rival(view, "ryan"));
		assertEquals("You lead your friends!", GrindProgress.rival(view, "Far"));
		assertEquals("Your public KC is unavailable", GrindProgress.rival(view, "Missing"));
		view = new FriendLeaderboard.View(Arrays.asList(new FriendLeaderboard.Row("Ryan", 100, ""),
			new FriendLeaderboard.Row("Tie", 100, "")), "Updated");
		assertEquals("Tie: 1 to pass", GrindProgress.rival(view, "Ryan"));
	}

	@Test public void doesNotClaimFirstPlaceWithMissingResults()
	{
		FriendLeaderboard.View view = new FriendLeaderboard.View(Arrays.asList(new FriendLeaderboard.Row("Ryan", 100, ""),
			new FriendLeaderboard.Row("Pending", null, "Waiting")), "Loading");
		assertEquals("No rival in loaded results", GrindProgress.rival(view, "Ryan"));
	}
}

package com.bosskillmilestones;

import net.runelite.api.GameState;
import org.junit.Test;
import static org.junit.Assert.*;

public class BossSidebarTest
{
	@Test public void regionLoadsPreserveExistingAccount()
	{
		assertTrue(BossSidebar.preserveDuringTransition(GameState.LOADING, "account", "account"));
		assertTrue(BossSidebar.preserveDuringTransition(GameState.LOADING, "account", null));
		assertTrue(BossSidebar.preserveDuringTransition(GameState.HOPPING, "account", "account"));
		assertTrue(BossSidebar.preserveDuringTransition(GameState.CONNECTION_LOST, "account", null));
	}

	@Test public void logoutAndAccountChangesAreNotPreserved()
	{
		assertFalse(BossSidebar.preserveDuringTransition(GameState.LOGIN_SCREEN, "account", "account"));
		assertFalse(BossSidebar.preserveDuringTransition(GameState.LOADING, "account", "other"));
		assertFalse(BossSidebar.preserveDuringTransition(GameState.LOADING, null, null));
		assertFalse(BossSidebar.preserveDuringTransition(GameState.LOGGED_IN, "account", "account"));
	}
}

package com.bosskillmilestones;

import org.junit.Test;
import static org.junit.Assert.*;

public class BossStatsTest
{
	@Test public void handlesLineBreakVariantsAndRejectsMalformedNumbers()
	{
		assertEquals(Integer.valueOf(1250), BossStats.parse("Kill Count:<BR/><col=fff>1,250</col><br />Best time: 1:30"));
		assertEquals(Integer.valueOf(24), BossStats.parse("Kills:\r\n24\r\n"));
		assertNull(BossStats.parse("Kills: 1,2,50"));
		assertNull(BossStats.parse(null));
		assertNull(BossStats.parse("Kills: 1,250\nCompletions: 100"));
	}
	@Test
	public void readsLabelledTotalsIncludingZero()
	{
		assertEquals(Integer.valueOf(1250), BossStats.parse("Kill count: <col=ff0000>1,250</col><br>Best time: 1:30"));
		assertEquals(Integer.valueOf(0), BossStats.parse("Kills:\n0\n"));
	}

	@Test
	public void rejectsAchievementsTimesAndAmbiguousModes()
	{
		assertNull(BossStats.parse("Tasks completed: 10/25\nBest time: 1:30"));
		assertNull(BossStats.parse("Kills: 10/25"));
		assertNull(BossStats.parse("Kills: 50\nKills: 100\n"));
		assertNull(BossStats.parse("Kill count: 9999999999999999"));
	}

	@Test
	public void bossNamesRejectOrdinaryNpcsAndShareKeys()
	{
		assertNull(BossNames.known("Goblin"));
		assertEquals("Sarachnis", BossNames.known("  SARACHNIS  "));
		assertEquals(BossNames.key(BossNames.known("The Nightmare")), BossNames.key(BossNames.known("Nightmare")));
	}
}

package com.bosskillmilestones;

import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Test;
import static org.junit.Assert.*;

public class OverlayActivityTest
{
	@Test
	public void requiresKillAndExpiresAtTimeout()
	{
		AtomicLong clock = new AtomicLong();
		OverlayActivity activity = new OverlayActivity(clock::get);
		assertFalse(activity.visible(false, 5));
		activity.killed();
		assertTrue(activity.visible(false, 5));
		clock.set(TimeUnit.MINUTES.toNanos(5) - 1);
		assertTrue(activity.visible(false, 5));
		clock.incrementAndGet();
		assertFalse(activity.visible(false, 5));
		activity.killed();
		assertTrue(activity.visible(false, 5));
	}

	@Test
	public void everyKillRefreshesTimerAndSettingsApplyImmediately()
	{
		AtomicLong clock = new AtomicLong();
		OverlayActivity activity = new OverlayActivity(clock::get);
		activity.killed();
		clock.set(TimeUnit.MINUTES.toNanos(4));
		activity.killed();
		clock.set(TimeUnit.MINUTES.toNanos(6));
		assertTrue(activity.visible(false, 5));
		assertFalse(activity.visible(false, 1));
		assertTrue(activity.visible(true, 1));
		assertFalse(activity.visible(false, 1));
	}

	@Test
	public void resetHidesUntilNewKillUnlessAlwaysOn()
	{
		OverlayActivity activity = new OverlayActivity(() -> 100L);
		assertTrue(activity.visible(true, 5));
		activity.killed();
		activity.reset();
		assertFalse(activity.visible(false, 5));
		assertTrue(activity.visible(true, 5));
	}
}

package com.bosskillmilestones;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.Skill;
import org.junit.Test;
import static org.junit.Assert.*;

public class FriendLeaderboardTest
{
	@Test public void normalizesAndDeduplicatesFriends()
	{
		assertEquals(Arrays.asList("Ryan", "A friend"), FriendLeaderboard.uniqueNames(
			Arrays.asList(" Ryan ", "ryan", null, "", "A\u00a0friend", "a friend")));
	}

	@Test public void sortsKillsDescendingWithoutTreatingMissingAsZero()
	{
		List<FriendLeaderboard.Row> rows = FriendLeaderboard.sorted(Arrays.asList(
			new FriendLeaderboard.Row("Unknown", null, "Unranked"),
			new FriendLeaderboard.Row("Zero", 0, ""),
			new FriendLeaderboard.Row("Zed", 100, ""),
			new FriendLeaderboard.Row("Amy", 100, "")));
		assertEquals("Amy", rows.get(0).name);
		assertEquals("Zed", rows.get(1).name);
		assertEquals(Integer.valueOf(0), rows.get(2).kills);
		assertNull(rows.get(3).kills);
	}

	@Test public void readsBossScoreNotRankOrExperience()
	{
		HiscoreSkill boss = BossNames.hiscore("Sarachnis");
		assertNotNull(boss);
		HiscoreResult result = new HiscoreResult("Ryan", Collections.singletonMap(boss, new Skill(12, 1250, -1)));
		assertEquals(Integer.valueOf(1250), FriendLeaderboard.row("Ryan", result, boss, false).kills);
		assertEquals("Unavailable", FriendLeaderboard.row("Ryan", result, boss, true).status);
		assertEquals("Unranked", FriendLeaderboard.row("Ryan", null, boss, false).status);
		HiscoreResult unranked = new HiscoreResult("Ryan", Collections.singletonMap(boss, new Skill(-1, -1, -1)));
		assertNull(FriendLeaderboard.row("Ryan", unranked, boss, false).kills);
	}

	@Test public void unsupportedTargetsDoNotRequestHiscores()
	{
		assertNull(BossNames.hiscore(TestGuard.NAME));
		assertNull(BossNames.hiscore("Theatre of Blood: Entry Mode"));
		assertNull(BossNames.hiscore(null));
		assertTrue(BossNames.all().contains(TestGuard.NAME));
	}
}

package com.bosskillmilestones;

import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import net.runelite.client.audio.AudioPlayer;
import org.junit.Test;
import static org.junit.Assert.*;

public class MilestoneAudioTest
{
	@Test
	public void mapsMilestonesToRequestedClips()
	{
		assertEquals("/audio/little-victory.wav", MilestoneAudio.resourceFor(10));
		assertEquals("/audio/golden-steps.wav", MilestoneAudio.resourceFor(25));
		assertEquals("/audio/little-victory.wav", MilestoneAudio.resourceFor(50));
		assertEquals("/audio/little-victory.wav", MilestoneAudio.resourceFor(100));
		assertEquals("/audio/champion-fanfare.wav", MilestoneAudio.resourceFor(250));
		assertEquals("/audio/legendary-victory.wav", MilestoneAudio.resourceFor(1000));
		assertNull(MilestoneAudio.resourceFor(0));
	}

	@Test
	public void bundledSoundsAreStandardPcmWav() throws Exception
	{
		for (Celebration celebration : Celebration.values())
		{
			try (InputStream resource = MilestoneAudio.class.getResourceAsStream(celebration.resource))
			{
				assertNotNull(resource);
				byte[] bytes = resource.readAllBytes();
				ByteBuffer header = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);
				assertEquals("RIFF", new String(bytes, 0, 4, StandardCharsets.US_ASCII));
				assertEquals("WAVE", new String(bytes, 8, 4, StandardCharsets.US_ASCII));
				assertEquals("fmt ", new String(bytes, 12, 4, StandardCharsets.US_ASCII));
				assertEquals(16, header.getInt(16));
				assertEquals(1, header.getShort(20)); // PCM, no codec required
				assertEquals(2, header.getShort(22));
				assertEquals(44100, header.getInt(24));
				assertEquals(16, header.getShort(34));
				assertEquals("data", new String(bytes, 36, 4, StandardCharsets.US_ASCII));
				assertEquals(bytes.length - 44, header.getInt(40));
				assertTrue(header.getInt(40) > 0);
				assertTrue((double) header.getInt(40) / header.getInt(28) < 6);
			}
		}
	}

	@Test public void delegatesPlaybackAndIgnoresRequestsWhileStopped() throws Exception
	{
		LinkedBlockingQueue<String> requests = new LinkedBlockingQueue<>();
		AudioPlayer player = new AudioPlayer()
		{
			@Override public void play(Class<?> owner, String path, float gain)
			{
				requests.add(owner.getName() + ":" + path + ":" + gain);
			}
		};
		MilestoneAudio audio = new MilestoneAudio(player);
		try
		{
			audio.play(Celebration.TEN);
			assertTrue(requests.isEmpty());
			audio.start();
			audio.play(Celebration.GOAL);
			assertEquals(MilestoneAudio.class.getName() + ":" + Celebration.GOAL.resource + ":0.0",
				requests.poll(3, TimeUnit.SECONDS));
			audio.stop();
			audio.play(Celebration.THOUSAND);
			assertTrue(requests.isEmpty());
		}
		finally { audio.stop(); }
	}

	@Test public void legacyClipsAreNotPackaged()
	{
		assertNull(MilestoneAudio.class.getResource("/audio/birthday-party-horn.wav"));
		assertNull(MilestoneAudio.class.getResource("/audio/community-claps.wav"));
		assertNull(MilestoneAudio.class.getResource("/audio/wow-thats-amazing.wav"));
	}
}

package com.bosskillmilestones;

import org.junit.Test;
import static org.junit.Assert.*;

public class KillSignalsTest
{
	@Test
	public void bothEventOrdersCountOnce()
	{
		for (boolean lootFirst : new boolean[]{false, true})
		{
			KillSignals signals = new KillSignals();
			assertTrue(signals.accept("sarachnis", lootFirst, 10));
			assertFalse(signals.accept("sarachnis", !lootFirst, 12));
		}
	}

	@Test
	public void matchesMultipleKillsOneToOne()
	{
		KillSignals signals = new KillSignals();
		assertTrue(signals.accept("boss", true, 10));
		assertTrue(signals.accept("boss", true, 11));
		assertFalse(signals.accept("boss", false, 12));
		assertFalse(signals.accept("boss", false, 13));
		assertTrue(signals.accept("boss", false, 14));
	}

	@Test
	public void differentBossesAndOldSignalsDoNotMatch()
	{
		KillSignals signals = new KillSignals();
		assertTrue(signals.accept("sarachnis", true, 10));
		assertTrue(signals.accept("zulrah", false, 11));
		assertTrue(signals.accept("sarachnis", false, 10 + KillSignals.MATCH_TICKS + 1));
	}

	@Test
	public void accountChangeClearsPairing()
	{
		KillSignals signals = new KillSignals();
		assertTrue(signals.accept("boss", true, 10));
		signals.clear();
		assertTrue(signals.accept("boss", false, 11));
	}
}

package com.bosskillmilestones;

import org.junit.Test;
import static org.junit.Assert.*;

public class CelebrationTest
{
	@Test public void escalatesAndRepeatsWithoutOverlappingSounds()
	{
		assertEquals(Celebration.TEN, Celebration.select(10, 10, 10, false));
		assertEquals(Celebration.TWENTY_FIVE, Celebration.select(25, 25, 25, false));
		assertEquals(Celebration.FIFTY, Celebration.select(50, 50, 10, false));
		assertEquals(Celebration.FIFTY, Celebration.select(150, 10, 10, false));
		assertEquals(Celebration.TWO_FIFTY, Celebration.select(250, 250, 25, false));
		assertEquals(Celebration.TWO_FIFTY, Celebration.select(750, 250, 25, false));
		assertEquals(Celebration.THOUSAND, Celebration.select(1000, 250, 25, false));
		assertEquals(Celebration.THOUSAND, Celebration.select(2000, 10, 10, false));
		assertEquals(Celebration.GOAL, Celebration.select(1000, 1000, 10, true));
	}

	@Test public void sessionEncouragementIsOptionalAndSeparate()
	{
		assertNull(Celebration.select(60, 10, 0, false));
		assertEquals(Celebration.SESSION, Celebration.select(60, 10, 10, false));
		assertEquals(Celebration.SESSION, Celebration.select(175, 25, 25, false));
		assertNull(Celebration.select(61, 11, 10, false));
		assertNull(Celebration.select(0, 0, 10, false));
	}

	@Test public void goalCompletionIsOneTimePerTarget()
	{
		assertFalse(Celebration.goalReached(0, 100, null));
		assertFalse(Celebration.goalReached(100, null, null));
		assertFalse(Celebration.goalReached(100, 99, null));
		assertTrue(Celebration.goalReached(100, 100, null));
		assertFalse(Celebration.goalReached(100, 101, 100));
		assertTrue(Celebration.goalReached(200, 200, 100));
	}
}

package com.bosskillmilestones;

import java.awt.Component;
import java.awt.Container;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.Arrays;
import javax.imageio.ImageIO;
import javax.swing.SwingUtilities;
import javax.swing.JTable;
import javax.swing.JScrollPane;
import org.junit.Test;
import static org.junit.Assert.*;

public class BossSidebarPanelTest
{
	@Test public void skullIsPixelSymmetricalAtEveryDisplaySize()
	{
		for (int size : new int[]{24, 48, 96})
		{
			BufferedImage icon = BossSidebarPanel.icon(size);
			for (int y = 0; y < size; y++)
				for (int x = 0; x < size / 2; x++)
					assertEquals("Symmetry at " + size + "px: " + x + "," + y,
						icon.getRGB(x, y), icon.getRGB(size - 1 - x, y));
		}
	}
	@Test public void rendersPluginHubIcon() throws Exception
	{
		BufferedImage icon = BossSidebarPanel.icon(48);
		assertEquals(48, icon.getWidth());
		assertEquals(48, icon.getHeight());
		ImageIO.write(icon, "png", new File("build/plugin-icon.png"));
	}
	@Test public void rendersPanelAndUpdatesCounters() throws Exception
	{
		SwingUtilities.invokeAndWait(() -> {
			BossSidebarPanel panel = new BossSidebarPanel(name -> {}, () -> {}, () -> {}, () -> {});
			assertTrue(panel.showProgress(new BossKillMilestonesPlugin.Progress("Sarachnis", 25, 150, "1250")));
			assertFalse(panel.showProgress(new BossKillMilestonesPlugin.Progress("Sarachnis", 26, 151, "1251", 2000)));
			panel.showRival("Boss Hunter: 1051 to pass");
			panel.showBoard(new FriendLeaderboard.View(Arrays.asList(
				new FriendLeaderboard.Row("Boss Hunter", 2300, ""),
				new FriendLeaderboard.Row("Ryan", 1250, ""),
				new FriendLeaderboard.Row("A Friend", null, "Unranked")), "Updated — cached up to 10 min"), "Ryan");
			JTable board = board(panel);
			assertEquals(4, board.getRowCount());
			assertEquals("2", board.getValueAt(0, 0));
			assertEquals("Ryan (you)", board.getValueAt(0, 1));
			assertEquals("1,250", board.getValueAt(0, 2));
			assertEquals("1", board.getValueAt(1, 0));
			assertEquals("Ryan (you)", board.getValueAt(2, 1));
			java.awt.Color green = board.prepareRenderer(board.getCellRenderer(0, 0), 0, 0).getForeground();
			assertTrue(green.getGreen() > green.getRed());
			assertEquals(board.getForeground(), board.prepareRenderer(board.getCellRenderer(1, 0), 1, 0).getForeground());
			panel.setSize(240, 800);
			layout(panel);
			BufferedImage image = new BufferedImage(240, 800, BufferedImage.TYPE_INT_ARGB);
			Graphics2D graphics = image.createGraphics();
			panel.paint(graphics);
			graphics.dispose();
			try { ImageIO.write(image, "png", new File("build/sidebar-preview.png")); }
			catch (java.io.IOException ex) { throw new AssertionError(ex); }
		});
	}

	@Test public void unrankedSummaryAndClearing() throws Exception
	{
		SwingUtilities.invokeAndWait(() -> {
			BossSidebarPanel panel = new BossSidebarPanel(name -> {}, () -> {}, () -> {}, () -> {});
			panel.showBoard(new FriendLeaderboard.View(Arrays.asList(
				new FriendLeaderboard.Row("Ryan", null, "Unranked")), "Updated"), "ryan");
			JTable board = board(panel);
			assertEquals(2, board.getRowCount());
			assertEquals("—", board.getValueAt(0, 0));
			assertEquals("Unranked", board.getValueAt(0, 2));
			panel.message("Logged out");
			assertEquals(0, board.getRowCount());
		});
	}

	private static JTable board(BossSidebarPanel panel)
	{
		for (Component child : panel.getComponents())
			if (child instanceof JScrollPane) return (JTable) ((JScrollPane) child).getViewport().getView();
		throw new AssertionError("Leaderboard missing");
	}

	private static void layout(Container container)
	{
		container.doLayout();
		for (Component child : container.getComponents())
			if (child instanceof Container) layout((Container) child);
	}
}

