		caption.setForeground(Color.LIGHT_GRAY);
		value.setForeground(Color.WHITE);
		row.add(caption, BorderLayout.WEST);
		row.add(value, BorderLayout.EAST);
		return row;
	}

	boolean showProgress(BossKillMilestonesPlugin.Progress progress)
	{
		boolean changed = !Objects.equals(shownBoss, progress.name);
		if (changed || shownGoal != progress.goal)
		{
			shownGoal = progress.goal;
			goalInput.setValue(progress.goal);
		}
		long next = GrindProgress.nextMilestone(progress.saved);
		milestone.setValue((int) (100.0 * progress.saved / next));
		milestone.setString("Next jingle: " + progress.saved + " / " + next);
		Integer lifetime = GrindProgress.total(progress.total);
		personal.setValue(progress.goal > 0 && lifetime != null ? (int) Math.min(100, 100.0 * lifetime / progress.goal) : 0);
		personal.setString(progress.goal <= 0 ? "Set a lifetime goal below" : lifetime == null ? "Goal " + progress.goal + " — sync total"
			: lifetime >= progress.goal ? "Goal reached! " + progress.goal : "Goal: " + progress.total + " / " + progress.goal);
		shownBoss = progress.name;
		title.setText(progress.name);
		title.setToolTipText(progress.name);
		total.setText(progress.total);
		saved.setText(Integer.toString(progress.saved));
		session.setText(Integer.toString(progress.session));
		if (changed) image.setIcon(new ImageIcon(icon(96)));
		return changed;
	}

	void showImage(String boss, BufferedImage sprite)
	{
		if (!Objects.equals(shownBoss, boss)) return;
		BufferedImage enlarged = new BufferedImage(96, 96, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = enlarged.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		double scale = Math.min(96.0 / sprite.getWidth(), 96.0 / sprite.getHeight());
		int width = (int) (sprite.getWidth() * scale), height = (int) (sprite.getHeight() * scale);
		graphics.drawImage(sprite, (96 - width) / 2, (96 - height) / 2, width, height, null);
		graphics.dispose();
		image.setIcon(new ImageIcon(enlarged));
	}

	void showRival(String text)
	{
		rival.setText(text);
		rival.setToolTipText("Cached public hiscores: " + text);
	}

	private static JProgressBar progressBar(Color color)
	{
		JProgressBar bar = new JProgressBar(0, 100);
		bar.setStringPainted(true);
		bar.setForeground(color);
		bar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
		return bar;
	}

	void showBoard(FriendLeaderboard.View view, String ownName)
	{
		table.setRowCount(0);
		hasOwnSummary = false;
		int rank = 0;
		for (FriendLeaderboard.Row row : view.rows)
		{
			table.addRow(new Object[]{row.kills == null ? "—" : Integer.toString(++rank),
				row.name + (row.name.equalsIgnoreCase(ownName) ? " (you)" : ""),
				row.kills == null ? row.status : String.format("%,d", row.kills)});
			if (row.name.replace('\u00a0', ' ').trim().equalsIgnoreCase(ownName == null ? "" : ownName.replace('\u00a0', ' ').trim()))
			{
				hasOwnSummary = true;
				// Copy this exact rank; the summary must not affect the ordered ranks.
				Object[] summary = {row.kills == null ? "—" : Integer.toString(rank), row.name + " (you)",
					row.kills == null ? row.status : String.format("%,d", row.kills)};
				table.insertRow(0, summary);
			}
		}
		status.setText(view.status);
	}

	void message(String text)
	{
		hasOwnSummary = false;
		table.setRowCount(0);
		status.setText(text);
	}

	@Override public void onActivate() { activate.run(); }
	@Override public void onDeactivate() { deactivate.run(); }

	static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.scale(size / 24.0, size / 24.0);
		g.setColor(new Color(255, 190, 80));
		g.fillRoundRect(5, 3, 14, 14, 7, 7);
		g.fillRect(8, 15, 8, 5);
		g.setColor(ColorScheme.DARK_GRAY_COLOR);
		g.fillOval(7, 8, 4, 4);
		g.fillOval(13, 8, 4, 4);
		// Filled, equally spaced gaps keep the three teeth centred on the skull.
		g.fillRect(10, 17, 1, 3);
		g.fillRect(13, 17, 1, 3);
		g.dispose();
		// Mirror the raster too, avoiding one-pixel antialiasing differences at
		// the small toolbar size as well as in the larger boss placeholder.
		for (int y = 0; y < size; y++)
			for (int x = 0; x < size / 2; x++)
				image.setRGB(size - 1 - x, y, image.getRGB(x, y));
		return image;
	}
}

package com.bosskillmilestones;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.inject.Singleton;
import javax.inject.Inject;
import net.runelite.client.audio.AudioPlayer;
import lombok.extern.slf4j.Slf4j;

@Singleton
@Slf4j
final class MilestoneAudio
{
	private ExecutorService worker;
	private final AudioPlayer audioPlayer;
	private int generation;

	@Inject
	MilestoneAudio(AudioPlayer audioPlayer)
	{
		this.audioPlayer = audioPlayer;
	}

	synchronized void start()
	{
		stop();
		worker = Executors.newSingleThreadExecutor(task -> {
			Thread thread = new Thread(task, "boss-milestone-audio");
			thread.setDaemon(true);
			return thread;
		});
	}

	synchronized void stop()
	{
		generation++;
		if (worker != null)
		{
			worker.shutdownNow();
			worker = null;
		}
	}

	static String resourceFor(int kills)
	{
		Celebration celebration = Celebration.select(kills, 0, 0, false);
		return celebration == null ? null : celebration.resource;
	}

	synchronized void play(Celebration celebration)
	{
		if (worker == null) return;
		int requestedGeneration = generation;
		worker.execute(() -> loadAndPlay(celebration.resource, requestedGeneration));
	}

	private void loadAndPlay(String resource, int requestedGeneration)
	{
		synchronized (this)
		{
			if (worker == null || generation != requestedGeneration) return;
		}
		try
		{
			// Resource decoding and playback stay off the client thread. RuneLite owns
			// the audio line lifecycle; an already-started cue finishes naturally.
			audioPlayer.play(MilestoneAudio.class, resource, 0f);
		}
		catch (Exception ex)
		{
			log.warn("Could not play milestone sound {}", resource, ex);
		}
	}
}

package com.bosskillmilestones;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

final class BossNames
{
	private static final Map<String, String> NAMES = new HashMap<>();
	static
	{
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			if (skill.getType() == HiscoreSkillType.BOSS)
			{
				NAMES.put(normalize(skill.getName()), skill.getName());
				if (skill.getName().startsWith("The "))
				{
					NAMES.put(normalize(skill.getName().substring(4)), skill.getName());
				}
			}
		}
		alias("The Nightmare", "Nightmare");
		alias("Dusk", "Grotesque Guardians");
		alias("Barrows chest", "Barrows Chests");
		alias("Barrows", "Barrows Chests");
		alias("Lunar chest", "Lunar Chests");
		alias("Theatre of Blood Entry Mode", "Theatre of Blood: Entry Mode");
		alias("Tombs of Amascut Entry Mode", "Tombs of Amascut: Entry Mode");
	}

	private static void alias(String alias, String name)
	{
		NAMES.put(normalize(alias), name);
	}

	static String known(String name)
	{
		return name == null ? null : NAMES.get(normalize(name));
	}

	static java.util.List<String> all()
	{
		java.util.TreeSet<String> names = new java.util.TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		names.addAll(NAMES.values());
		names.add(TestGuard.NAME);
		return new java.util.ArrayList<>(names);
	}

	static HiscoreSkill hiscore(String name)
	{
		if (name == null) return null;
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			if (skill.getType() == HiscoreSkillType.BOSS && normalize(skill.getName()).equals(normalize(name))) return skill;
		}
		return null;
	}

	static String normalize(String name)
	{
		return name.replace(':', ' ').replace('\u00a0', ' ').trim().toLowerCase(Locale.ROOT).replaceAll("\\s+", " ");
	}

	static String key(String name)
	{
		return normalize(name).replaceAll("[^a-z0-9]+", "-").replaceAll("^-|-$", "");
	}
}

package com.bosskillmilestones;

final class GrindProgress
{
	static long nextMilestone(int kills)
	{
		return kills < 10 ? 10 : kills < 25 ? 25 : ((long) kills / 50 + 1) * 50;
	}

	static Integer total(String text)
	{
		try { return Integer.valueOf(text.replace("~", "").replace(",", "")); }
		catch (NumberFormatException ex) { return null; }
	}

	static String rival(FriendLeaderboard.View view, String own)
	{
		Integer kills = null;
		for (FriendLeaderboard.Row row : view.rows)
			if (sameName(row.name, own)) kills = row.kills;
		if (kills == null) return "Your public KC is unavailable";
		FriendLeaderboard.Row next = null;
		boolean incomplete = false;
		for (FriendLeaderboard.Row row : view.rows)
		{
			if (row.kills == null) incomplete = true;
			if (!sameName(row.name, own) && row.kills != null && row.kills >= kills
				&& (next == null || row.kills < next.kills)) next = row;
		}
		if (next == null) return incomplete ? "No rival in loaded results" : "You lead your friends!";
		return next.name + ": " + ((long) next.kills - kills + 1) + " to pass";
	}

	private static boolean sameName(String left, String right)
	{
		return right != null && left.replace('\u00a0', ' ').trim().equalsIgnoreCase(right.replace('\u00a0', ' ').trim());
	}
}

package com.bosskillmilestones;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;

final class BossMilestoneOverlay extends OverlayPanel
{
	private final Client client;
	private final BossKillMilestonesPlugin plugin;
	private final BossKillMilestonesConfig config;

	@Inject
	BossMilestoneOverlay(Client client, BossKillMilestonesPlugin plugin, BossKillMilestonesConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(260, 0));
		panelComponent.setBackgroundColor(new Color(20, 25, 32, 225));
		panelComponent.setBorder(new java.awt.Rectangle(10, 10, 10, 10));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay() || client.getGameState() != GameState.LOGGED_IN || !plugin.isCounterVisible()) return null;
		BossKillMilestonesPlugin.Progress progress = plugin.getProgress();
		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder().text(progress.name).color(new Color(255, 190, 80)).build());
		add("This session", Integer.toString(progress.session));
		add("Since enabled", Integer.toString(progress.saved));
		add("Total", progress.total);
		if (config.showGrindGoals())
		{
			long next = GrindProgress.nextMilestone(progress.saved);
			add("NEXT JINGLE", (next - progress.saved) + " kills away");
			bar(progress.saved, next, progress.saved + " / " + next, new Color(225, 170, 65));
			Integer total = GrindProgress.total(progress.total);
			if (progress.goal > 0)
			{
				add("PERSONAL GOAL", total == null ? "Sync lifetime total" : total >= progress.goal ? "Reached!" : (progress.goal - total) + " to go");
				bar(total == null ? 0 : total, progress.goal, progress.total + " / " + progress.goal, new Color(65, 165, 145));
			}
			else add("Personal goal", "Set in sidebar");
			add("FRIEND TO BEAT", "Cached hiscores");
			panelComponent.getChildren().add(LineComponent.builder().left(plugin.rivalFor(progress.name))
				.leftColor(new Color(130, 210, 255)).build());
		}
		return super.render(graphics);
	}

	private void bar(long value, long maximum, String label, Color color)
	{
		ProgressBarComponent bar = new ProgressBarComponent();
		bar.setMaximum(maximum);
		bar.setValue(Math.min(value, maximum));
		bar.setForegroundColor(color);
		bar.setBackgroundColor(new Color(40, 47, 57));
		bar.setCenterLabel(label);
		bar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.TEXT_ONLY);
		panelComponent.getChildren().add(bar);
	}

	private void add(String label, String value)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(label).right(value).build());
	}
}

package com.bosskillmilestones;

enum Celebration
{
	SESSION("session-spark", "Session milestone"),
	TEN("little-victory", "First ten"),
	TWENTY_FIVE("golden-steps", "First twenty-five"),
	FIFTY("little-victory", "Milestone"),
	TWO_FIFTY("champion-fanfare", "250-kill milestone"),
	THOUSAND("legendary-victory", "1,000-kill milestone"),
	GOAL("goal-complete", "Personal goal reached");

	final String resource;
	final String title;
	Celebration(String resource, String title)
	{
		this.resource = "/audio/" + resource + ".wav";
		this.title = title;
	}

	static Celebration select(int saved, int session, int sessionInterval, boolean goalReached)
	{
		if (goalReached) return GOAL;
		if (saved > 0 && saved % 1000 == 0) return THOUSAND;
		if (saved > 0 && saved % 250 == 0) return TWO_FIFTY;
		if (saved > 0 && saved % 50 == 0) return FIFTY;
		if (saved == 25) return TWENTY_FIVE;
		if (saved == 10) return TEN;
		if ((sessionInterval == 10 || sessionInterval == 25) && session > 0 && session % sessionInterval == 0) return SESSION;
		return null;
	}

	static boolean goalReached(int target, Integer total, Integer celebrated)
	{
		return target > 0 && total != null && total >= target && !Integer.valueOf(target).equals(celebrated);
	}
}

package com.bosskillmilestones;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
