@ConfigGroup("boss-kill-milestones")
public interface BossKillMilestonesConfig extends Config
{
	@ConfigItem(keyName = "sessionCelebrations", name = "Session encouragement", description = "Optional short celebrations every 10 or 25 session kills per boss. Larger milestones and personal goals take priority.")
	default SessionEncouragement sessionCelebrations() { return SessionEncouragement.OFF; }

	enum SessionEncouragement
	{
		OFF(0), EVERY_10(10), EVERY_25(25);
		final int interval;
		SessionEncouragement(int interval) { this.interval = interval; }
		@Override public String toString() { return interval == 0 ? "Off" : "Every " + interval + " kills"; }
	}
	@ConfigItem(keyName = "showGrindGoals", name = "Show goals on overlay", description = "Show milestone progress, personal goals and cached friend comparisons on the on-screen counter.")
	default boolean showGrindGoals() { return true; }

	@ConfigItem(keyName = "friendHiscores", name = "Friends hiscore leaderboard",
		description = "Look up your account and friends' public main-game boss totals. Requests send each username to the official hiscores service; results are cached for 10 minutes.",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers")
	default boolean friendHiscores()
	{
		return false;
	}

	@ConfigItem(keyName = "alwaysOnGui", name = "Always on GUI", description = "Keep the kill counter visible before your first kill and ignore the idle timeout. Show kill counter must also be enabled.")
	default boolean alwaysOnGui()
	{
		return false;
	}

	@Range(min = 1, max = 60)
	@ConfigItem(keyName = "guiTimeoutMinutes", name = "GUI timeout (minutes)", description = "Hide the counter after this many minutes without a tracked kill. Ignored when Always on GUI is enabled.")
	default int guiTimeoutMinutes()
	{
		return 5;
	}

	@ConfigItem(keyName = "showOverlay", name = "Show kill counter", description = "Show the current target, session kills, saved kills and lifetime total.")
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(keyName = "testGuard", name = "Varrock guard testing", description = "Track level 21 Guards in Varrock as a separate test target. Uses server loot even when boss loot backup is off.")
	default boolean testGuard()
	{
		return false;
	}

	@ConfigItem(keyName = "syncDiagnostics", name = "Debug lifetime sync", description = "Report unreadable Combat Achievements boss statistics in chat and the debug log. Turn off after troubleshooting.")
	default boolean syncDiagnostics() { return false; }

	@ConfigItem(keyName = "lootBackup", name = "Loot backup", description = "Count recognised boss server-loot events when a kill-count message is missing.")
	default boolean lootBackup()
	{
		return true;
	}

	@ConfigItem(keyName = "syncReminder", name = "Initial sync reminder", description = "Remind you at login until a boss total has been read from Combat Achievements.")
	default boolean syncReminder()
	{
		return true;
	}

	@ConfigItem(
		keyName = "excludedBosses",
		name = "Excluded bosses",
		description = "Comma-separated boss names to exclude, matching the name shown in the kill-count message."
	)
	default String excludedBosses()
	{
		return "\n \n \n";
	}

	@ConfigItem(
		keyName = "playMilestoneSound",
		name = "Play milestone sound",
		description = "Play a celebratory sound when a boss milestone is reached."
	)
	default boolean playMilestoneSound()
	{
		return true;
	}
}

package com.bosskillmilestones;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.atomic.AtomicLong;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Nameable;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Singleton
final class BossSidebar
{
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ClientToolbar toolbar;
	@Inject private SpriteManager sprites;
	@Inject private ConfigManager configManager;
	@Inject private BossKillMilestonesConfig config;
	@Inject private BossKillMilestonesPlugin plugin;
	@Inject private FriendLeaderboard leaderboard;
	private final AtomicLong lifecycle = new AtomicLong();
	private final AtomicLong boardVersion = new AtomicLong();
	private volatile BossSidebarPanel panel;
	private NavigationButton navigation;
	private volatile boolean running;
	// The following state is owned by the client thread.
	private boolean active;
	private String selected;
	private volatile String profile;
	private String context;
	private String pictured;
	private final java.util.Map<String, String> rivals = new java.util.concurrent.ConcurrentHashMap<>();

	String rivalFor(String boss)
	{
		return config.friendHiscores() ? rivals.getOrDefault(boss, "Open sidebar to load friends") : "Enable friends hiscores to compare";
	}

	void start()
	{
		running = true;
		long life = lifecycle.incrementAndGet();
		leaderboard.start();
		SwingUtilities.invokeLater(() -> {
			if (!running || life != lifecycle.get()) return;
			if (navigation != null) toolbar.removeNavigation(navigation);
			panel = new BossSidebarPanel(boss -> clientThread.invokeLater(() -> {
				selected = boss; context = null; update();
			}), () -> clientThread.invokeLater(() -> { context = null; update(); }),
				() -> clientThread.invokeLater(() -> { active = true; context = null; update(); }),
				() -> clientThread.invokeLater(() -> {
					active = false; context = null; boardVersion.incrementAndGet(); leaderboard.cancel();
				}), (boss, goal) -> {
				String account = profile;
				clientThread.invokeLater(() -> {
					if (Objects.equals(account, configManager.getRSProfileKey())) { plugin.saveGoal(boss, goal); update(); }
				});
			});
			navigation = NavigationButton.builder().tooltip("Boss Milestones: Rank Among Friends")
				.icon(BossSidebarPanel.icon(24)).priority(7).panel(panel).build();
			toolbar.addNavigation(navigation);
			clientThread.invokeLater(() -> {
				if (life != lifecycle.get()) return;
				active = false; selected = null; profile = null; context = null; pictured = null; update();
			});
		});
	}

	void stop()
	{
		running = false;
		long life = lifecycle.incrementAndGet();
		boardVersion.incrementAndGet();
		leaderboard.stop();
		rivals.clear();
		SwingUtilities.invokeLater(() -> {
			if (life != lifecycle.get()) return;
			if (navigation != null) toolbar.removeNavigation(navigation);
			navigation = null; panel = null;
		});
	}

	void requestUpdate()
	{
		clientThread.invokeLater(this::update);
	}

	void update()
	{
		BossSidebarPanel target = panel;
		if (!running || target == null) return;
		// Region loading is not a logout: player/profile data may briefly be absent.
		if (preserveDuringTransition(client.getGameState(), profile, configManager.getRSProfileKey()))
		{
			if (!config.friendHiscores())
			{
				boardVersion.incrementAndGet(); leaderboard.cancel(); context = null;
				ui(target, () -> target.message("Enable Friends hiscore leaderboard in the plugin settings."));
			}
			return;
		}
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN
			&& configManager.getRSProfileKey() != null && client.getLocalPlayer() != null;
		String account = loggedIn ? configManager.getRSProfileKey() : null;
		if (!Objects.equals(profile, account))
		{
			profile = account; context = null; pictured = null;
			boardVersion.incrementAndGet(); leaderboard.clear();
			rivals.clear();
		}
		String boss = loggedIn ? (selected == null ? plugin.getActiveBoss() : selected) : null;
		BossKillMilestonesPlugin.Progress progress = loggedIn ? plugin.progressFor(boss)
			: new BossKillMilestonesPlugin.Progress("Log in to view kills", 0, 0, "Unknown");
		ui(target, () -> target.showProgress(progress));
		ui(target, () -> target.showRival(boss == null ? "Choose a boss" : rivalFor(boss)));
		HiscoreSkill skill = BossNames.hiscore(boss);
		if (!Objects.equals(pictured, boss))
		{
			pictured = boss;
			if (skill != null && skill.getSpriteId() >= 0)
			{
				sprites.getSpriteAsync(skill.getSpriteId(), 0, image -> ui(target, () -> target.showImage(boss, image)));
			}
		}
		String message = !loggedIn ? "Log in to view your account's friends."
			: !config.friendHiscores() ? "Enable Friends hiscore leaderboard in the plugin settings."
			: skill == null ? "Choose a boss with public hiscores. No hiscores are available for the test guard or entry modes."
			: !active ? "Open this panel to load friends." : null;
		List<String> names = new ArrayList<>();
		String own = loggedIn ? client.getLocalPlayer().getName() : null;
		if (message == null)
		{
			if (client.getFriendContainer() != null)
				for (Nameable friend : client.getFriendContainer().getMembers()) names.add(friend.getName());
			names.sort(String.CASE_INSENSITIVE_ORDER);
			names.add(0, own);
		}
		List<String> roster = FriendLeaderboard.uniqueNames(names);
		String nextContext = account + "|" + boss + "|" + message + "|" + roster;
		if (nextContext.equals(context)) return;
		context = nextContext;
		long version = boardVersion.incrementAndGet();
		leaderboard.cancel();
		if (message != null)
		{
			ui(target, () -> { if (version == boardVersion.get()) target.message(message); });
			return;
		}
		leaderboard.refresh(roster, skill, view -> ui(target, () -> {
			if (version == boardVersion.get())
			{
				String rival = GrindProgress.rival(view, own);
				rivals.put(boss, rival);
				target.showRival(rival);
				target.showBoard(view, own);
			}
		}));
	}

	static boolean preserveDuringTransition(GameState state, String previousProfile, String currentProfile)
	{
		return previousProfile != null && (currentProfile == null || previousProfile.equals(currentProfile))
			&& (state == GameState.LOADING || state == GameState.HOPPING || state == GameState.CONNECTION_LOST);
	}

	private void ui(BossSidebarPanel target, Runnable action)
	{
		long life = lifecycle.get();
		SwingUtilities.invokeLater(() -> {
			if (running && life == lifecycle.get() && panel == target) action.run();
		});
	}
}

package com.bosskillmilestones;

import net.runelite.api.coords.WorldPoint;

final class TestGuard
{
	static final String NAME = "Varrock guard (test)";

	static boolean matches(String name, int combatLevel, WorldPoint location)
	{
		// ServerNpcLoot has no NPC location, so limit its generic Guard composition
		// to a player on the surface in Varrock, including the city gates.
		return "Guard".equalsIgnoreCase(name) && combatLevel == 21 && location != null
			&& location.getPlane() == 0 && location.getX() >= 3170 && location.getX() <= 3290
			&& location.getY() >= 3370 && location.getY() <= 3510;
	}
}

package com.bosskillmilestones;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

/** Matches opposite signals one-to-one. Same-source kills remain separate. */
final class KillSignals
{
	static final int MATCH_TICKS = 8;
	private final List<Signal> signals = new ArrayList<>();

	boolean accept(String boss, boolean loot, int tick)
	{
		Iterator<Signal> iterator = signals.iterator();
		while (iterator.hasNext())
		{
			Signal signal = iterator.next();
			if (tick - signal.tick > MATCH_TICKS || tick < signal.tick)
			{
				iterator.remove();
			}
			else if (signal.boss.equals(boss) && signal.loot != loot)
			{
				iterator.remove();
				return false;
			}
		}
		signals.add(new Signal(boss, loot, tick));
		return true;
	}

	void clear()
	{
		signals.clear();
	}

	private static final class Signal
	{
		private final String boss;
		private final boolean loot;
		private final int tick;

		private Signal(String boss, boolean loot, int tick)
		{
			this.boss = boss;
			this.loot = loot;
			this.tick = tick;
		}
	}
}
